      let o = nebe(F, "#7EB0E2", "#F2E8D4") + mraky(F, r, 4, 26, 70, 90);
      o += voda(F, r, "M-10 150 L420 148 L420 176 L-10 178 Z", "#3E8AC0", "#1E6094", 152, 176, 8);
