      const obrys = function(x, y, w, h){ return clenit([[x - w, y], [x - w * 1.02, y - h * .3], [x - w * .86, y - h * .66], [x - w * .55, y - h * .92], [x - w * .12, y - h], [x + w * .3, y - h * .96], [x + w * .66, y - h * .8], [x + w * .9, y - h * .5], [x + w * 1.02, y - h * .22], [x + w, y]], q, .22, .05, 3); };
