  ["more1", "more2", "souse1", "souse2"].forEach(function(k){
    const c = rgb(barvitVitalitu && k.indexOf("souse") === 0 ? barvy["souse-vit"] : barvy[k]); g.uniform3f(u["u_" + k], c[0], c[1], c[2]); });
