  const fakt = prvek("section", "fakt-oddil");
  fakt.appendChild(prvek("p", "fakt", j.fakt));
  if (VYMYSLENE.stopy[j.id]) fakt.appendChild(prvek("p", "stopa", "✦ " + VYMYSLENE.stopy[j.id][T.lang]));   // stopa k Bráně („mellon“)
  let kde = null;
