    if (v.typ === "bezrodu") [a, b].forEach(function(L){ if (BEZ_RODU.has(L.rod)) rod.appendChild(prvek("p", null, t("bezRodu", {a: jmenoL(L), druh: REJSTRIK.rr[L.rod]}))); });
