    rod.appendChild(prvek("p", null, v.koren ? t("pribuzneKoren", {r: REJSTRIK.rr[a.rod]}) : t("pribuzneSpolecny", {v: T.lang === "cs" && PD.vetve[PD.uzly[v.u]] ? nazevVetve(v.u, a.rod).toLowerCase() : nazevVetve(v.u, a.rod)})));
